export function getHandleConfig(e){const t={n:{edges:["n"]},s:{edges:["s"]},e:{edges:["e"]},w:{edges:["w"]},ne:{edges:["n","e"]},nw:{edges:["n","w"]},se:{edges:["s","e"]},sw:{edges:["s","w"]}};return t[e]||null}export function clamp(e,t,n){return Math.max(t,Math.min(n,e))}export function computeResizeRect(e,t,n,s,c,o,g){let{top:d,left:i,width:l,height:p}=e;if(n.includes("e")&&(l=clamp(l+t.x,s,o)),n.includes("s")&&(p=clamp(p+t.y,c,g)),n.includes("w")){const e=clamp(l-t.x,s,o);i+=l-e,l=e}if(n.includes("n")){const e=clamp(p-t.y,c,g);d+=p-e,p=e}return{top:d,left:i,width:l,height:p}}